import{_ as l,l as i,o as e,c as n,v as o,p as s,x as t,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"簿的均场极限","description":"","frontmatter":{"title":"簿的均场极限","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/lob-mean-field.md","filePath":"quant/lob-mean-field.md","lastUpdated":1789023840000}'),c={name:"quant/lob-mean-field.md"};function m(u,a,E,_,A,f){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="簿的均场极限" tabindex="-1">簿的均场极限 <a class="header-anchor" href="#簿的均场极限" aria-label="Permalink to &quot;簿的均场极限&quot;">​</a></h1><div class="epigraph"><p>当到达的订单无穷多、每一笔无穷小，限价簿的状态可以用深度密度的偏微分方程来描述。个体博弈收成对这个密度的反应，密度再由个体行动自洽。</p><footer>—— Cont, Stoikov and Talreja, A stochastic model for order book dynamics, Operations Research, 2010；均场控制的交易拥挤见 Cardaliaguet and Lehalle, Mean field game of controls and an application to trade crowding, Mathematics and Financial Economics, 2018</footer></div><p><a href="/quant/lob-shape-macro">宏观形状</a>是经验直方图。缺口是：直方图能否作为大量微观订单的极限定律被推导出来，而不是只被测量。Cont、Stoikov 与 Talreja（2010）用独立到达的点过程描述各档增减；Cardaliaguet 与 Lehalle（2018）把拥挤执行写成均场博弈。本课只取「从个体到密度」这一层，不把统计物理的整套场论搬进来，也不重推单期 \\(\\lambda\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Parlour 的状态是两个整数队长，维数随档数爆炸。均场用密度 \\(\\rho(t,p)\\) 表示价格 \\(p\\) 附近的深度，到达、撤单、成交写成对 \\(\\rho\\) 的算子。问题是两类模型的分工：若订单流被当成外生强度（Cont 等），形状是排队系统的稳态，没有策略；若交易者对拥挤反应（均场博弈），强度对 \\(\\rho\\) 内生，出现拥堵反馈。前者适合描述，后者适合问「大家都用同样执行算法时冲击如何变」。</p><p>Kyle 的连续拍卖已经是一种均场：噪声布朗、知情者对价格函数最优。限价簿均场把价格函数换成整条密度，状态更富，解析更少。</p><h3 id="外生强度-vs-对密度的控制" tabindex="-1">外生强度 vs 对密度的控制 <a class="header-anchor" href="#外生强度-vs-对密度的控制" aria-label="Permalink to &quot;外生强度 vs 对密度的控制&quot;">​</a></h3><p>CST（2010）：限价、市价、撤单是独立泊松，强度可依赖价差等低维状态，稳态可算、可校准到事件流。预测是统计的。均场博弈：每个小交易者选交易速率，成本依赖所有人加总的永久冲击，均衡是 PDE–HJB 系统。预测是策略的：公告同时执行会自我加重冲击。Admati–Pfleiderer 的聚集在连续密度上变成拥挤外部性。</p><p><span class="marginnote">Lasry–Lions 均场博弈是数学框架。本课只引用它在订单流拥挤上的应用，不讲一般存在性定理。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>点过程簿：各档深度是生灭过程，市价把对方近端吃掉并可能改变价差状态。校准用各事件类型的强度。输出：价差分布、形状、首达时间。它能复制宏观轮廓的一部分，但不能解释强度从哪来。</p><p>均场执行：代表性交易者最小化冲击 + 等待，冲击是平均场 \\(\\mu_t\\) 的函数。均衡时 \\(\\mu\\) 等于个体最优的加总。比较静态：同时段目标越多，瞬时 \\(\\lambda\\) 式成本越高，最优是错开——与策略噪声相反的「避开拥挤」。现实里截止时间不允许任意错开，于是收盘密度出现尖峰。</p><h3 id="从密度再读" tabindex="-1">从密度再读 \\(P(Q)\\) <a class="header-anchor" href="#从密度再读" aria-label="Permalink to &quot;从密度再读 $P(Q)$&quot;">​</a></h3><p>给定 \\(\\rho\\)，市价 \\(Q\\) 沿密度积分得到即时价格。\\(\\rho\\) 随机或随场变化时，冲击过程有持续性。这为非线性冲击与平方根冲击等经验定律提供一条「形状积分」通道，而不是从 Kyle 线性出发再假设临时冲击函数。临时/永久冲击课已有执行侧叙述；这里只强调簿密度是那个函数的状态基础。</p>',14)),(e(),s(p,null,{default:t(()=>[h(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20Agents%5B%22%E8%AE%B8%E5%A4%9A%E5%B0%8F%E8%AE%A2%E5%8D%95%22%5D%20--%3E%20Rho%5B%22%E6%B7%B1%E5%BA%A6%E5%AF%86%E5%BA%A6%20%CF%81(t%2Cp)%22%5D%0A%20%20Rho%20--%3E%20Cost%5B%22%E5%86%B2%E5%87%BB%E4%B8%8E%E7%AD%89%E5%BE%85%22%5D%0A%20%20Cost%20--%3E%20Agents%0A%20%20Exog%5B%22%E5%A4%96%E7%94%9F%E6%B3%8A%E6%9D%BE%E5%BC%BA%E5%BA%A6%22%5D%20--%3E%20Rho%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>均场极限抹掉队内名次，只保留密度——FIFO 的位置租金在极限里变成密度的局部高度，时间优先的微观价值被平均掉。因此均场更接近 pro-rata 或「无穷可分订单」的世界，用来谈形状与拥挤合适，用来谈抢一个队头不合适。速度竞赛是有限人、非均场的博弈，下一单元开始。</p><p>外生点过程把撤单写成强度，能拟合高撤单率，但不解释为什么强度在新闻时跳。把强度条件于公共信息，就回到 Foucault 被捡，只是写在密度上。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>独立泊松忽略订单流自相关（Hawkes）。无穷小订单忽略手数栅格与冰山。校准过的 CST 模型常低估真实冲击凸性，因为缺少策略同步。均场博弈的对称假设在「一个巨鹰对一群小单」时失效，那是 Kyle 单一知情者的领地。</p><p><span class="marginnote">不要用均场 PDE 去给某一档的队头排队时间做精确预测。名次是离散对象，要回 Parlour / 队列反应模型。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>均场把簿写成深度密度：外生点过程给出可校准稳态，均场博弈给出拥挤外部性。</li><li>极限抹掉 FIFO 名次，适合形状与同步执行，不适合队头抢位。</li><li>冲击函数可以由密度积分得到，而不必回到单期线性 \\(\\lambda\\)。</li><li>出处：Cont, Stoikov and Talreja, <em>Operations Research</em>, 2010；Cardaliaguet and Lehalle, <em>Mathematics and Financial Economics</em>, 2018；形状对照 Bouchaud, Mézard and Potters, 2002。</li></ul>',8))])}const P=l(c,[["render",m]]);export{B as __pageData,P as default};
